using System;using System.Linq;using System.Collections.Generic;using HarborCity.RoadCore;
static class CityBatchRecoveryChecks {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}
 static World Fixture(int count,out int future,int lanes=1){var w=new World();int a=w.AddJunction(new Point()),b=w.AddJunction(new Point(3000,0,0)),c=w.AddJunction(new Point(4000,0,0)),d=w.AddJunction(new Point(3000,0,100));w.AddRoad(a,b,new[]{w.JunctionPosition(a),w.JunctionPosition(b)},lanes:lanes);future=w.AddRoad(b,c,new[]{w.JunctionPosition(b),w.JunctionPosition(c)},lanes:lanes);w.AddRoad(b,d,new[]{w.JunctionPosition(b),w.JunctionPosition(d)},lanes:lanes);w.AddRoad(d,c,new[]{w.JunctionPosition(d),w.JunctionPosition(c)},lanes:lanes);int source=w.AddDepot(a,10000),target=w.AddDepot(c,0);for(int i=0;i<count;i++){Check(w.Dispatch(source,target,1,0)!=null,"Fixture spawn");w.Advance(.2);}return w;}
 static void Pair(World w,string label,int expected){var data=SaveCodec.Write(w);var old=SaveCodec.Read(data);var batch=SaveCodec.Read(data);var positions=batch.Vehicles.ToDictionary(v=>v.id,v=>batch.Position(v));int n=0;foreach(var v in old.Vehicles)if(v.status==VehicleStatus.Stranded&&old.TryResumeStranded(v.id))n++;int actual=batch.ResumeStrandedVehicles();Check(n==actual&&actual==expected,label+" resumed count");Check(SaveCodec.Write(old).SequenceEqual(SaveCodec.Write(batch)),label+" exact paths/status/tasks/cargo/positions");foreach(var v in batch.Vehicles)Check(Point.Distance(positions[v.id],batch.Position(v))<1e-7,label+" moved a vehicle");old.Validate();old.AssertSafety();batch.Validate();batch.AssertSafety();Check(batch.ResumeStrandedVehicles()==0,label+" repeated recovery changed result");var cold=SaveCodec.Read(SaveCodec.Write(batch));for(int i=0;i<80;i++){old.Advance(.05);batch.Advance(.05);cold.Advance(.05);Check(SaveCodec.Write(old).SequenceEqual(SaveCodec.Write(batch))&&SaveCodec.Write(cold).SequenceEqual(SaveCodec.Write(batch)),label+" cold/legacy continuation");}Console.WriteLine("PASS "+label);}
 static void Main(){Pair(new World(),"empty",0);int future;var w=Fixture(1,out future);Pair(w,"no stranded",0);w.RemoveRoad(future);Pair(w,"one detour",1);w=Fixture(64,out future);w.RemoveRoad(future);Pair(w,"64 detours",64);
 w=Fixture(12,out future);int e=w.AddJunction(new Point(10000,0,0)),f=w.AddJunction(new Point(11000,0,0));int isolated=w.AddRoad(e,f,new[]{w.JunctionPosition(e),w.JunctionPosition(f)});int from=w.AddDepot(e),to=w.AddDepot(f,0);Check(w.Dispatch(from,to)!=null,"Isolated spawn");w.Advance(.2);w.RemoveRoad(future);w.RemoveRoad(isolated);Pair(w,"mixed lost surface and detours",12);
 w=Fixture(4,out future);w.RemoveRoad(1);Pair(w,"unrecoverable",0);
 w=Fixture(1,out future,2);w.Advance(3);var car=w.Vehicles.First();Check(w.TryChangeLane(car.id,1-w.Network.Get(car.Current).LaneIndex),"Begin lane change");w.Advance(.25);car.Freeze(w.Position(car));Pair(w,"in-flight lane change",1);
 // Exact old single-car oracle on a frozen actor already inside a connection.
 w=Fixture(1,out future);for(int i=0;i<10000&&!w.Network.Get(w.Vehicles.First().Current).IsConnection;i++)w.Advance(.05);car=w.Vehicles.First();Check(w.Network.Get(car.Current).IsConnection,"Reach junction fixture");car.Freeze(w.Position(car));Pair(w,"junction prefix",1);
 // Fault injection proves full validation was retained and failed candidates
 // cannot partially change live routes/status/epoch. Invalid cargo is not gameplay.
 w=Fixture(4,out future);w.RemoveRoad(future);car=w.Vehicles.Last();car.Task.Shipment.remaining=-1;var before=SaveCodec.Write(w);long epoch=w.EditEpoch;bool threw=false;try{w.ResumeStrandedVehicles();}catch(ArgumentException){threw=true;}catch(InvalidOperationException){threw=true;}Check(threw&&before.SequenceEqual(SaveCodec.Write(w))&&epoch==w.EditEpoch,"Failed batch partially changed live world or skipped cargo validation");
 Console.WriteLine("PASS "+checks+" batch recovery checks: original sequential paths/state, zero/all/mixed failures, change/junction, cold continuation and validation rollback");}
}
